public class InnerConnectionTypePaginationConfigurationFactory(Action<Humidifier.Glue.ConnectionTypeTypes.PaginationConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Glue.ConnectionTypeTypes.PaginationConfiguration>
{

    internal InnerConnectionTypeCursorConfigurationFactory CursorConfigurationFactory { get; set; }

    internal InnerConnectionTypeOffsetConfigurationFactory OffsetConfigurationFactory { get; set; }

    protected override Humidifier.Glue.ConnectionTypeTypes.PaginationConfiguration Create()
    {
        var paginationConfigurationResult = CreatePaginationConfiguration();
        factoryAction?.Invoke(paginationConfigurationResult);

        return paginationConfigurationResult;
    }

    private Humidifier.Glue.ConnectionTypeTypes.PaginationConfiguration CreatePaginationConfiguration()
    {
        var paginationConfigurationResult = new Humidifier.Glue.ConnectionTypeTypes.PaginationConfiguration();

        return paginationConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Glue.ConnectionTypeTypes.PaginationConfiguration result)
    {
        base.CreateChildren(result);

        result.CursorConfiguration ??= CursorConfigurationFactory?.Build();
        result.OffsetConfiguration ??= OffsetConfigurationFactory?.Build();
    }

} // End Of Class

